// Step 1 (rest of it) — normalize the RealtyAPI response into a flat list
// of property items, mirroring shadescout/clients/realty.py
// _extract_records / _to_listings_realtyapi.
//
// Response shape confirmed against live calls: GET /search/byzip wraps
// results as [{"searchResults": [...], "total": N, ...}], and each record
// carries realtor.com-style fields — an `address` object ({line, city,
// state_code, postal_code, latitude, longitude}), plus last_sold_date,
// last_sold_price, list_price, status. The alternate key names below are
// fallbacks for other spellings behind the same aggregator.

const ADDRESS_KEYS = ['formattedAddress', 'full_address', 'fullAddress', 'address', 'streetAddress', 'location'];
const SALE_DATE_KEYS = ['last_sold_date', 'lastSaleDate', 'soldDate', 'sold_date', 'closeDate', 'close_date', 'dateSold'];
const PRICE_KEYS = ['last_sold_price', 'lastSalePrice', 'soldPrice', 'sold_price', 'list_price', 'price', 'closePrice'];
const CONTAINER_KEYS = ['searchResults', 'results', 'properties', 'listings', 'data', 'homes'];

function first(record, keys) {
  for (const key of keys) {
    if (record[key] !== undefined && record[key] !== null && record[key] !== '') return record[key];
  }
  return null;
}

function formatAddress(value) {
  if (typeof value === 'string') return value;
  if (value && typeof value === 'object') {
    const parts = [
      first(value, ['line', 'street', 'streetAddress']),
      value.city,
      first(value, ['state_code', 'state']),
      first(value, ['postal_code', 'zip', 'zipcode']),
    ].filter(Boolean);
    return parts.length ? parts.join(', ') : null;
  }
  return null;
}

function extractCoords(record) {
  const candidates = [];
  if (record.address && typeof record.address === 'object') candidates.push(record.address);
  candidates.push(record);
  for (const candidate of candidates) {
    const lat = first(candidate, ['latitude', 'lat']);
    const lng = first(candidate, ['longitude', 'lng', 'lon']);
    if (lat !== null && lng !== null && !isNaN(Number(lat)) && !isNaN(Number(lng))) {
      return { lat: Number(lat), lng: Number(lng) };
    }
  }
  return null;
}

function daysSince(isoDate) {
  const parsed = new Date(isoDate);
  if (isNaN(parsed.getTime())) return null;
  return Math.floor((Date.now() - parsed.getTime()) / 86400000);
}

const body = $input.first().json;
const candidates = Array.isArray(body) ? body : [body];

let records = null;
for (const candidate of candidates) {
  if (!candidate || typeof candidate !== 'object') continue;
  for (const key of CONTAINER_KEYS) {
    if (Array.isArray(candidate[key])) {
      if (candidate[key].length === 0 && candidate.message) {
        // e.g. [{"message": "404: zipCode required for /search/byzip",
        //        "searchResults": [], ...}] — an error disguised as an
        //        empty result rather than a non-2xx status.
        throw new Error('RealtyAPI /search/byzip returned an error: ' + candidate.message);
      }
      records = candidate[key];
      break;
    }
  }
  if (records) break;
}

if (!records && Array.isArray(body) && body.every((item) => item && typeof item === 'object')) {
  records = body; // top-level list of raw records, no envelope wrapper
}

if (!records) {
  throw new Error('RealtyAPI response had no recognizable list of properties. Keys seen: ' + JSON.stringify(Object.keys(body || {})));
}

const config = $('Config').first().json;

const listings = [];
for (const record of records) {
  const address = formatAddress(first(record, ADDRESS_KEYS));
  if (!address) continue;
  const saleDate = first(record, SALE_DATE_KEYS);
  if (saleDate) {
    const age = daysSince(saleDate);
    if (age !== null && age > config.maxDaysSinceSale) continue;
  }
  listings.push({
    formattedAddress: address,
    lastSaleDate: saleDate,
    price: first(record, PRICE_KEYS),
    coordinates: extractCoords(record),
  });
}

listings.sort((a, b) => (b.lastSaleDate || '').localeCompare(a.lastSaleDate || ''));

return listings.slice(0, config.limit).map((listing) => ({ json: listing }));

// Steps 3-7 for every property that survived normalization: resolve
// coordinates (RealtyAPI records already embed lat/lng, so Google
// Geocoding only runs as a fallback for records without them), fetch
// satellite + street view imagery, run the OpenRouter vision analysis
// with the exact required prompt, apply the has_patio/already_covered
// filter, and build the postcard copy. Mirrors shadescout/pipeline.py
// process_property + build_postcard_text. Runs once for ALL items so a
// failure on one property can be caught and skipped without dropping the
// whole batch — matching the Python pipeline's per-property error
// isolation.

const properties = $input.all();

// Paste your keys (and vision model) directly below — no separate Config
// node needed for any of this, no $env/$vars needed (works on every n8n
// instance including Cloud). This trades convenience for the key living
// in the workflow JSON in plain text: fine for a private/personal
// workflow, not for anything you'll export or share.
const GOOGLE_MAPS_API_KEY = 'PASTE_YOUR_GOOGLE_MAPS_API_KEY_HERE';
const OPENROUTER_API_KEY = 'PASTE_YOUR_OPENROUTER_API_KEY_HERE';
// OpenRouter model slug. OpenRouter retires/renames slugs over time — if
// this 404s, check https://openrouter.ai/models for a current
// vision-capable one and edit it right here.
const VISION_MODEL = 'google/gemini-3.5-flash';

// Fail loudly and early on missing credentials — otherwise every property
// errors inside the per-property try/catch and the node returns an empty
// result with no explanation.
if (!GOOGLE_MAPS_API_KEY || GOOGLE_MAPS_API_KEY.startsWith('PASTE_')) {
  throw new Error('Set GOOGLE_MAPS_API_KEY at the top of this Code node (replace the PASTE_... placeholder).');
}
if (!OPENROUTER_API_KEY || OPENROUTER_API_KEY.startsWith('PASTE_')) {
  throw new Error('Set OPENROUTER_API_KEY at the top of this Code node (replace the PASTE_... placeholder).');
}
const GOOGLE_KEY = GOOGLE_MAPS_API_KEY;
const OPENROUTER_KEY = OPENROUTER_API_KEY;

// n8n's httpRequest helper (axios-based) only puts "Request failed with
// status code NNN" on err.message — the actual response body (which
// usually names the real problem, e.g. an invalid OpenRouter model slug
// or a disabled Google API) is on err.response and gets lost by a bare
// try/catch. Wrap every call with a label so failures are diagnosable.
async function safeRequest(label, options) {
  try {
    return await this.helpers.httpRequest(options);
  } catch (err) {
    const status = err.response?.status ?? err.statusCode ?? err.cause?.response?.status ?? 'unknown';
    const rawBody = err.response?.data ?? err.cause?.response?.data;
    const body = typeof rawBody === 'string'
      ? rawBody.slice(0, 300)
      : rawBody ? JSON.stringify(rawBody).slice(0, 300) : err.message;
    throw new Error(`${label} (${options.method} ${options.url}) failed: status=${status} body=${body}`);
  }
}

const PROMPT = `Image 1 below is a top-down satellite view (zoom 20) of the property. Image 2 is a street-level view of the same address for additional context.

You are an expert landscape and shade analyst. Look at this satellite image of a residential property.
1. Does this home have a backyard patio or deck? (Yes/No)
2. Is there already a solid roof, pergola, or heavy tree cover shading the patio? (Yes/No)
3. Based on the sun's trajectory (assume south-facing gets the most sun in the US), estimate how many hours of direct, punishing sunlight this patio gets per day.
4. Return ONLY a valid JSON object exactly like this: {"has_patio": true, "already_covered": false, "estimated_sun_hours": 10}`;

async function geocodeAddress(address) {
  const geo = await safeRequest.call(this, 'Google Geocoding fallback', {
    method: 'GET',
    url: 'https://maps.googleapis.com/maps/api/geocode/json',
    qs: { address, key: GOOGLE_KEY },
    json: true,
  });
  if (geo.status !== 'OK' || !geo.results || !geo.results.length) return null;
  return geo.results[0].geometry.location; // { lat, lng }
}

async function fetchImageBase64(label, url, qs) {
  const buffer = await safeRequest.call(this, label, { method: 'GET', url, qs, encoding: 'arraybuffer' });
  return Buffer.from(buffer).toString('base64');
}

async function fetchUpcomingHotDay(lat, lng) {
  try {
    const weather = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.open-meteo.com/v1/forecast',
      qs: {
        latitude: lat,
        longitude: lng,
        daily: 'temperature_2m_max',
        temperature_unit: 'fahrenheit',
        forecast_days: 7,
        timezone: 'auto',
      },
      json: true,
    });
    const highs = weather?.daily?.temperature_2m_max || [];
    const dates = weather?.daily?.time || [];
    if (!highs.length) return null;
    const idx = highs.indexOf(Math.max(...highs));
    const day = new Date(dates[idx]).toLocaleDateString('en-US', { weekday: 'long' });
    return { day, tempF: Math.round(highs[idx]) };
  } catch (err) {
    return null; // best-effort only, matches shadescout/clients/weather.py
  }
}

function buildPostcardText(sunHours, hotDay) {
  if (hotDay) {
    return `Your patio takes ${sunHours} hours of direct sun a day. This ${hotDay.day} it hits ${hotDay.tempF}°. Scan this QR code to see how a louvered pergola looks in your exact backyard.`;
  }
  return `Your patio takes ${sunHours} hours of direct, punishing sun a day. Scan this QR code to see how a louvered pergola looks in your exact backyard.`;
}

const qualifiedLeads = [];
const runLog = []; // one line per property so an empty result is explainable

for (const item of properties) {
  const property = item.json;
  const address = property.formattedAddress;

  try {
    let coords = property.coordinates;
    if (!coords) {
      coords = await geocodeAddress.call(this, address);
      if (!coords) {
        runLog.push(`SKIP ${address}: geocoding returned no result`);
        continue;
      }
    }
    const { lat, lng } = coords;

    const satelliteB64 = await fetchImageBase64.call(this, 'Google Static Maps', 'https://maps.googleapis.com/maps/api/staticmap', {
      center: `${lat},${lng}`,
      zoom: 20,
      maptype: 'satellite',
      size: '640x640',
      key: GOOGLE_KEY,
    });
    const streetB64 = await fetchImageBase64.call(this, 'Google Street View', 'https://maps.googleapis.com/maps/api/streetview', {
      location: `${lat},${lng}`,
      size: '640x640',
      key: GOOGLE_KEY,
    });

    const visionResp = await safeRequest.call(this, 'OpenRouter vision', {
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        Authorization: `Bearer ${OPENROUTER_KEY}`,
        'Content-Type': 'application/json',
      },
      body: {
        model: VISION_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'text', text: PROMPT },
              { type: 'image_url', image_url: { url: `data:image/png;base64,${satelliteB64}` } },
              { type: 'image_url', image_url: { url: `data:image/png;base64,${streetB64}` } },
            ],
          },
        ],
      },
      json: true,
    });

    const content = visionResp?.choices?.[0]?.message?.content;
    const match = content && content.match(/\{[\s\S]*\}/);
    if (!match) {
      runLog.push(`SKIP ${address}: vision model returned no parseable JSON: ${String(content).slice(0, 120)}`);
      continue;
    }

    const analysis = JSON.parse(match[0]);
    if (!analysis.has_patio || analysis.already_covered) {
      runLog.push(
        `DISQUALIFIED ${address}: has_patio=${analysis.has_patio}, already_covered=${analysis.already_covered}`
      );
      continue;
    }

    const sunHours = Number(analysis.estimated_sun_hours);
    const hotDay = await fetchUpcomingHotDay.call(this, lat, lng);

    // Attach the analyzed images as binary data so they're viewable in the
    // n8n execution panel (Output > Binary tab) and usable by downstream
    // nodes (e.g. attach to an email or upload to Drive).
    const binary = {};
    binary.satellite = await this.helpers.prepareBinaryData(
      Buffer.from(satelliteB64, 'base64'), 'satellite.png', 'image/png'
    );
    binary.street_view = await this.helpers.prepareBinaryData(
      Buffer.from(streetB64, 'base64'), 'street_view.png', 'image/png'
    );

    runLog.push(`QUALIFIED ${address}: ${sunHours}h sun`);
    qualifiedLeads.push({
      json: {
        lead_status: 'QUALIFIED',
        property_address: address,
        coordinates: { lat, lng },
        sun_hours: sunHours,
        postcard_text: buildPostcardText(sunHours, hotDay),
      },
      binary,
    });
  } catch (err) {
    // isolate failures per-property instead of aborting the whole run,
    // but keep the reason so an empty result is diagnosable
    runLog.push(`ERROR ${address}: ${err.message}`);
    continue;
  }
}

console.log('ShadeScout run log:\n' + runLog.join('\n'));

if (qualifiedLeads.length === 0) {
  // Surface WHY instead of silently returning nothing.
  throw new Error('No qualified leads. Per-property outcomes:\n' + (runLog.join('\n') || '(no properties received)'));
}

return qualifiedLeads;

// Step: for every already-qualified lead from node 3, generate a
// photorealistic backyard render (pergola installed), a true 360-degree
// equirectangular panorama of that render, and — only if GENERATE_VIDEO
// is turned on — a 5-second teaser video via OpenRouter's async video
// API (Seedance 2.0 Fast). These are visual assets for the outreach
// pitch, not a new filter: every input item is still returned even if
// generation fails for it, with the reason recorded in the run log.
//
// OpenRouter's Image API (POST /api/v1/images) and Video API
// (POST /api/v1/videos) are new-ish surfaces; the request/response shape
// below is built from OpenRouter's published docs/blog, not a live test
// run (their doc pages block automated fetching). If a field name here
// is wrong, safeRequest will surface the exact status + response body so
// it's a one-line fix, same as every other integration in this workflow.

const items = $input.all();

// Paste your OpenRouter key below (same one used in node 3). Video
// generation is OFF by default — it's an async job that takes minutes
// and is billed per generation, so flip GENERATE_VIDEO to true only once
// you've reviewed a lead and actually want to send it.
const OPENROUTER_API_KEY = 'PASTE_YOUR_OPENROUTER_API_KEY_HERE';
// Image model slug (generation + editing from reference images). Check
// https://openrouter.ai/models if this 404s.
const IMAGE_MODEL = 'google/gemini-2.5-flash-image';
// Video model slug. Check https://openrouter.ai/models if this 404s.
const VIDEO_MODEL = 'bytedance/seedance-2.0-fast';
const GENERATE_VIDEO = false;

if (!OPENROUTER_API_KEY || OPENROUTER_API_KEY.startsWith('PASTE_')) {
  throw new Error('Set OPENROUTER_API_KEY at the top of this Code node (replace the PASTE_... placeholder).');
}
const OPENROUTER_KEY = OPENROUTER_API_KEY;

async function safeRequest(label, options) {
  try {
    return await this.helpers.httpRequest(options);
  } catch (err) {
    const status = err.response?.status ?? err.statusCode ?? err.cause?.response?.status ?? 'unknown';
    const rawBody = err.response?.data ?? err.cause?.response?.data;
    const body = typeof rawBody === 'string'
      ? rawBody.slice(0, 300)
      : rawBody ? JSON.stringify(rawBody).slice(0, 300) : err.message;
    throw new Error(`${label} (${options.method} ${options.url}) failed: status=${status} body=${body}`);
  }
}

const RENDER_PROMPT = "Using the two reference photos (an overhead satellite view and a street-level view of the same house), generate a single photorealistic image of this exact backyard patio with a modern louvered pergola installed over it. Match the home's visible roofline, siding/brick color, and materials from the references. Natural daylight, realistic shadows, no people, no text or watermarks.";

const PANORAMA_PROMPT = "Take the backyard scene in the reference image and re-render it as a full 360-degree equirectangular panorama: 2:1 aspect ratio, seamless left-and-right edges that wrap into one continuous scene, consistent lighting, the same pergola-covered patio as the centerpiece. Equirectangular projection suitable for a 360 photo viewer.";

const VIDEO_PROMPT = "A slow, smooth cinematic camera pan across this shaded backyard patio, revealing the pergola overhead and warm late-afternoon sunlight. 5 seconds, no text, no people.";

async function generateImage(label, promptText, referenceDataUris) {
  const resp = await safeRequest.call(this, label, {
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/images',
    headers: {
      Authorization: `Bearer ${OPENROUTER_KEY}`,
      'Content-Type': 'application/json',
    },
    body: {
      model: IMAGE_MODEL,
      prompt: promptText,
      input_references: referenceDataUris,
    },
    json: true,
  });
  // Response shape is best-effort (see note at top of this node) — try
  // the most likely locations for the generated image and normalize to
  // base64 either way.
  const img = resp?.data?.[0] || resp?.images?.[0] || resp?.output?.[0] || resp;
  const b64 = img?.b64_json || img?.base64 || img?.image_base64;
  if (b64) return b64;
  const url = img?.url || img?.image_url;
  if (url) {
    const buffer = await safeRequest.call(this, `${label} (download)`, { method: 'GET', url, encoding: 'arraybuffer' });
    return Buffer.from(buffer).toString('base64');
  }
  throw new Error(`${label}: could not find an image in the response: ${JSON.stringify(resp).slice(0, 300)}`);
}

async function generateVideo(label, promptText, firstFrameDataUri) {
  const submitResp = await safeRequest.call(this, `${label} (submit)`, {
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/videos',
    headers: {
      Authorization: `Bearer ${OPENROUTER_KEY}`,
      'Content-Type': 'application/json',
    },
    body: {
      model: VIDEO_MODEL,
      prompt: promptText,
      duration: 5,
      aspect_ratio: '16:9',
      frame_images: [{ url: firstFrameDataUri, frame_type: 'first_frame' }],
    },
    json: true,
  });
  const jobId = submitResp.id || submitResp.job_id;
  const pollingUrl = submitResp.polling_url || (jobId ? `https://openrouter.ai/api/v1/videos/${jobId}` : null);
  if (!pollingUrl) {
    throw new Error(`${label}: submit response had no polling_url/id: ${JSON.stringify(submitResp).slice(0, 300)}`);
  }

  const maxAttempts = 48; // ~4 minutes at 5s/poll
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    await new Promise((resolve) => setTimeout(resolve, 5000));
    const status = await safeRequest.call(this, `${label} (poll)`, {
      method: 'GET',
      url: pollingUrl,
      headers: { Authorization: `Bearer ${OPENROUTER_KEY}` },
      json: true,
    });
    if (status.status === 'completed') {
      const videoUrl = status.unsigned_urls?.[0] || status.output?.[0]?.url;
      if (!videoUrl) throw new Error(`${label}: completed but no unsigned_urls in response: ${JSON.stringify(status).slice(0, 300)}`);
      const buffer = await safeRequest.call(this, `${label} (download)`, { method: 'GET', url: videoUrl, encoding: 'arraybuffer' });
      return Buffer.from(buffer);
    }
    if (status.status === 'failed') {
      throw new Error(`${label}: job failed: ${JSON.stringify(status).slice(0, 300)}`);
    }
  }
  throw new Error(`${label}: timed out waiting for video after ${maxAttempts * 5}s`);
}

const output = [];
const runLog = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const address = item.json.property_address;
  const binary = { ...item.binary };

  try {
    const satelliteBuffer = await this.helpers.getBinaryDataBuffer(i, 'satellite');
    const streetBuffer = await this.helpers.getBinaryDataBuffer(i, 'street_view');
    const satelliteDataUri = `data:image/png;base64,${satelliteBuffer.toString('base64')}`;
    const streetDataUri = `data:image/png;base64,${streetBuffer.toString('base64')}`;

    const renderB64 = await generateImage.call(this, 'OpenRouter backyard render', RENDER_PROMPT, [satelliteDataUri, streetDataUri]);
    binary.backyard_render = await this.helpers.prepareBinaryData(
      Buffer.from(renderB64, 'base64'), 'backyard_render.png', 'image/png'
    );
    runLog.push(`RENDER_OK ${address}`);

    const panoramaB64 = await generateImage.call(this, 'OpenRouter panorama', PANORAMA_PROMPT, [`data:image/png;base64,${renderB64}`]);
    binary.panorama = await this.helpers.prepareBinaryData(
      Buffer.from(panoramaB64, 'base64'), 'panorama.png', 'image/png'
    );
    runLog.push(`PANORAMA_OK ${address}`);

    if (GENERATE_VIDEO) {
      try {
        const videoBuffer = await generateVideo.call(this, 'OpenRouter video', VIDEO_PROMPT, `data:image/png;base64,${panoramaB64}`);
        binary.teaser_video = await this.helpers.prepareBinaryData(videoBuffer, 'teaser.mp4', 'video/mp4');
        runLog.push(`VIDEO_OK ${address}`);
      } catch (videoErr) {
        runLog.push(`VIDEO_FAILED ${address}: ${videoErr.message}`);
      }
    } else {
      runLog.push(`VIDEO_SKIPPED ${address} (GENERATE_VIDEO=false)`);
    }
  } catch (err) {
    // Render/panorama failure doesn't drop the lead — the postcard text
    // from node 3 is still valid without these bonus visuals.
    runLog.push(`RENDER_FAILED ${address}: ${err.message}`);
  }

  output.push({ json: item.json, binary });
}

console.log('ShadeScout render/video run log:\n' + runLog.join('\n'));

return output;
